struct FuzzMatcherApi : public i18n::phonenumbers::MatcherApi {
  bool MatchNationalNumber(const std::string& number,
                           const i18n::phonenumbers::PhoneNumberDesc& number_desc,
                           bool allow_prefix_match) const override {
    // Ensure the input contains only decimal digits per API contract.
    for (char c : number) { if (c < '0' || c > '9') return false; }
    const std::string &pat = number_desc.national_number_pattern();
    // Try to parse patterns of the form ^[0-9]{n}$ or ^[0-9]{min,max}$.
    auto parse_uint = [](const std::string& s, size_t* idx)->int { long v = 0; *idx = 0; while (*idx < s.size() && isdigit((unsigned char)s[*idx])) { v = v*10 + (s[*idx]-'0'); (*idx)++; } return (int)v; };
    if (pat.rfind("^[0-9]{", 0) == 0 && !pat.empty() && pat.back() == '$') {
      size_t brace_open = pat.find('{');
      size_t brace_close = pat.find('}', brace_open == std::string::npos ? 0 : brace_open);
      if (brace_open != std::string::npos && brace_close != std::string::npos && brace_close > brace_open + 1) {
        std::string inside = pat.substr(brace_open + 1, brace_close - brace_open - 1);
        size_t idx = 0; int a = parse_uint(inside, &idx);
        if (idx == inside.size()) {
          // exact ^{n}$
          return (int)number.size() == a || (allow_prefix_match && (int)number.size() <= a);
        }
        if (idx < inside.size() && inside[idx] == ',') {
          size_t idx2 = idx + 1; int b = parse_uint(inside.substr(idx2), &idx2);
          int min_len = a; int max_len = (idx2 ? b : a);
          if (min_len < 0) min_len = 0; if (max_len < min_len) max_len = min_len;
          int n = (int)number.size();
          if (n >= min_len && n <= max_len) return true;
          if (allow_prefix_match && n < min_len) return true; // treat as prefix acceptable
          return false;
