};

struct SimpleRegExp : public i18n::phonenumbers::RegExp {
  std::string pat;
  explicit SimpleRegExp(const std::string& p) : pat(p) {}
  bool Consume(i18n::phonenumbers::RegExpInput* input, bool anchor_at_start,
               std::string* m1, std::string* m2, std::string* m3,
               std::string* m4, std::string* m5, std::string* m6) const override {
    if (!input) return false;
    std::string text = input->ToString();
    size_t pos = anchor_at_start ? 0u : text.find(pat);
    if (pos == std::string::npos) return false;
    if (m1) *m1 = text.substr(pos, pat.size());
    if (m2) *m2 = pat;
    (void)m3; (void)m4; (void)m5; (void)m6; // unused captures
    // Note: SimpleInput has no cursor API; we cannot advance state. This is acceptable for fuzzing coverage.
    return true;
  }
  bool Match(const std::string& input_string, bool full_match, std::string* matched_string) const override {
    bool ok = false;
    if (full_match) ok = (input_string == pat);
    else ok = (input_string.find(pat) != std::string::npos);
    if (ok && matched_string) *matched_string = pat;
    return ok;
  }
  bool Replace(std::string* s, bool global, const std::string& repl) const override {
    if (!s) return false;
    bool changed = false;
    size_t pos = 0;
    if (pat.empty()) return false; // avoid infinite loop
    while (true) {
      pos = s->find(pat, pos);
      if (pos == std::string::npos) break;
      s->replace(pos, pat.size(), repl);
      changed = true;
      if (!global) break;
      pos += repl.size();
    }
    return changed;
  }
};

struct SimpleFactory : public i18n::phonenumbers::AbstractRegExpFactory {
  i18n::phonenumbers::RegExpInput* CreateInput(const std::string& utf8_input) const override {
    return new SimpleInput(utf8_input);
  }
  i18n::phonenumbers::RegExp* CreateRegExp(const std::string& utf8_regexp) const override {
    // Accept any bytes as a literal pattern; avoid heavy compilation costs.
    return new SimpleRegExp(utf8_regexp);
  }
  ~SimpleFactory() override {}
};

i18n::phonenumbers::AbstractRegExpFactory *factory = new SimpleFactory();
// Initialize lifetime/accounting attributes used by other stubs to enforce safe destruction.
FUZZ_SET_ATTR_INT(factory, "child_count", 0);
FUZZ_SET_ATTR_INT(factory, "re_count", 0);
