import random
import string
from typing import List

# We generate "arbitrary string" inputs that are nevertheless interesting for
# libphonenumber usage in the provided stubs: phone numbers in various formats,
# region codes, regex patterns, carrier codes, RFC3966, alpha numbers, etc.
# The fuzzer harness consumes these via FUZZ_PARAM_STR/FILENAME. We return a
# single bytes buffer; the harness will split/consume as needed.

MAX_TOTAL = 4096

ALPHA = string.ascii_letters
DIGITS = string.digits
HEX = string.hexdigits.lower()
WS = " \t\r\n"
PUNCT = "-()./\\"  # common dialable punctuation
PLUS = "+"

# Some real 2-letter regions to increase valid-code paths
REGIONS = [
    "US", "CA", "GB", "DE", "FR", "ES", "IT", "JP", "CN", "KR",
    "AU", "NZ", "BR", "AR", "MX", "IN", "RU", "ZA", "SE", "NO",
    "FI", "DK", "NL", "BE", "CH", "AT", "IE", "PT", "PL", "CZ",
]

# Common phone-like strings to seed parsing/formatting paths
E164_EXAMPLES = [
    "+14155552671", "+442079460123", "+33123456789", "+819012345678",
    "+61293744000", "+5511999998888", "+918888777666", "+8613800138000",
]
NATIONAL_EXAMPLES = [
    "(415) 555-2671", "020 7946 0123", "01 23 45 67 89", "090-1234-5678",
    "02 9374 4000", "(11) 99999-8888", "08888 77766", "13800138000",
]
RFC3966_EXAMPLES = [
    "tel:+1-415-555-2671", "tel:+44-20-7946-0123;ext=123", "tel:0800-111-222",
]
ALPHA_NUMBERS = [
    "1-800-FLOWERS", "1-888-APPLE", "0800-CONTACTS", "+1-800-GO-UHAUL",
]
CARRIER_CODES = ["", "0", "1", "9", "15", "0011", "010", "020", "555"]

# Useful regex patterns for NumberFormat and RegExp paths
REGEX_PATTERNS = [
    r"(\d{2,4})(\d+)",
    r"(\d{3})(\d{3})(\d+)",
    r"^(?:\+|00)(\d{1,3})(\d+)$",
    r"\D+",
    r"[A-Za-z]+",
]
REGEX_REPLACEMENTS = [r"$1-$2", r"$1 $2 $3", r"+$1 $2", "X", "Y"]

ENUM_NAMES = [
    "PhoneNumber_CountryCodeSource_UNSPECIFIED",
    "PhoneNumber_CountryCodeSource_FROM_NUMBER_WITH_PLUS_SIGN",
    "PhoneNumber_CountryCodeSource_FROM_NUMBER_WITH_IDD",
    "PhoneNumber_CountryCodeSource_FROM_NUMBER_WITHOUT_PLUS_SIGN",
    "PhoneNumber_CountryCodeSource_FROM_DEFAULT_COUNTRY",
]

def rand_choice(rng: random.Random, seq: List[str]) -> str:
    return seq[rng.randrange(len(seq))]

def rand_region(rng: random.Random) -> str:
    if rng.random() < 0.8:
        return rand_choice(rng, REGIONS)
    # fabricate two letters
    return chr(rng.randrange(65, 91)) + chr(rng.randrange(65, 91))

def rand_digits(rng: random.Random, lo: int, hi: int) -> str:
    n = rng.randrange(lo, hi+1)
    return ''.join(rng.choice(DIGITS) for _ in range(n))

def rand_alpha(rng: random.Random, lo: int, hi: int) -> str:
    n = rng.randrange(lo, hi+1)
    return ''.join(rng.choice(ALPHA) for _ in range(n))

def make_phone_like(rng: random.Random) -> str:
    typ = rng.random()
    if typ < 0.25:
        return rand_choice(rng, E164_EXAMPLES)
    if typ < 0.5:
        return rand_choice(rng, NATIONAL_EXAMPLES)
    if typ < 0.65:
        return rand_choice(rng, RFC3966_EXAMPLES)
    if typ < 0.8:
        return rand_choice(rng, ALPHA_NUMBERS)
    # Construct random but plausible: +<cc><nsn> with punctuation
    cc_len = rng.choice([1,2,3])
    cc = rand_digits(rng, cc_len, cc_len)
    nsn = rand_digits(rng, 6, 12)
    # insert punctuation occasionally
    pieces = []
    i = 0
    while i < len(nsn):
        step = rng.randrange(2, 5)
        pieces.append(nsn[i:i+step])
        i += step
    sep = rng.choice([" ", "-", "", "."]) if pieces else ""
    return "+" + cc + sep + sep.join(pieces)

def make_regionish(rng: random.Random) -> str:
    # The stubs sanitize to 2 letters, but also accept arbitrary strings.
    if rng.random() < 0.85:
        return rand_region(rng)
    return rand_alpha(rng, 1, 4)

def make_regex_pair(rng: random.Random) -> str:
    pat = rand_choice(rng, REGEX_PATTERNS) if rng.random() < 0.7 else random_regex(rng)
    rep = rand_choice(rng, REGEX_REPLACEMENTS)
    return f"{pat}\n{rep}"

def random_regex(rng: random.Random) -> str:
    atoms = [r"\d", r"\D", r"[A-Za-z]", r"[0-9]", r"\s", r"\S"]
    parts = []
    for _ in range(rng.randrange(2, 6)):
        a = rng.choice(atoms)
        q = rng.choice(["", "+", "*", "{2,4}", "?"])
        parts.append(a + q)
    if rng.random() < 0.3:
        parts.insert(0, "^")
    if rng.random() < 0.3:
        parts.append("$")
    return ''.join(parts)

def make_unicodeish(rng: random.Random) -> str:
    # Mix ASCII with some multi-byte UTF-8 sequences
    s = []
    for _ in range(rng.randrange(8, 64)):
        r = rng.random()
        if r < 0.7:
            s.append(rng.choice(string.printable))
        elif r < 0.9:
            # Latin-1 supplement encoded to UTF-8
            s.append(chr(rng.randrange(0x00A1, 0x00FF)))
        else:
            # Some BMP chars
            s.append(chr(rng.randrange(0x0400, 0x04FF)))  # Cyrillic block
    return ''.join(s)

def make_enum_name(rng: random.Random) -> str:
    if rng.random() < 0.8:
        return rand_choice(rng, ENUM_NAMES)
    # invalid-ish name sometimes
    return "ENUM_" + rand_alpha(rng, 3, 12)

def make_filenameish(rng: random.Random) -> str:
    # Some stubs may use FUZZ_PARAM_FILENAME indirectly; provide plausible name
    base = rand_alpha(rng, 3, 8)
    ext = rng.choice([".txt", ".proto", ".json", ".bin", ".dat"]) if rng.random() < 0.7 else ""
    return base + ext

def assemble_chunks(rng: random.Random) -> bytes:
    chunks: List[bytes] = []
    def add(s: str):
        chunks.append(s.encode('utf-8', errors='ignore'))
        chunks.append(b"\n")
    # Mix of items tailored to the stubs' consumption order variety.
    for _ in range(rng.randrange(2, 5)):
        add(make_phone_like(rng))
        add(make_regionish(rng))
        add(rand_choice(rng, CARRIER_CODES))
        add(make_regex_pair(rng))
        add(make_unicodeish(rng))
        add(make_enum_name(rng))
        add(make_filenameish(rng))
        # Also raw random chunk that may include punctuation significant to parser
        rand_chunk = ''.join(rng.choice(DIGITS + ALPHA + PUNCT + WS + PLUS) for _ in range(rng.randrange(10, 80)))
        add(rand_chunk)
    blob = b''.join(chunks)
    return blob[:MAX_TOTAL]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    return assemble_chunks(rng)

import random
from typing import List

# Target data type: "decimal digits string" (ASCII digits 0-9 only)
# Ensure we never request randint with invalid ranges when remaining < 2.

MAX_LEN = 32

_patterns: List[str] = [
    "0",
    "1",
    "911",
    "112",
    "101",
    "123",
    "000",
    "999",
    "1234567",
    "5550100",
    "202",
    "1800",
    "800",
    "44",
    "49",
    "33",
    "91",
]

def _asc_seq(n: int) -> str:
    return ''.join(str((i % 10)) for i in range(n))

def _desc_seq(n: int) -> str:
    return ''.join(str((9 - (i % 10))) for i in range(n))

def _repeat_digit(d: str, n: int) -> str:
    return d * n

def _rand_len(rng: random.Random, lo: int, hi: int) -> int:
    # Clamp and handle cases where hi < lo gracefully
    if hi < lo:
        return lo
    return rng.randint(lo, hi)

def _random_chunk(rng: random.Random, remaining: int) -> str:
    if remaining <= 0:
        return ""
    # Choose among several chunk styles
    choice = rng.randrange(6)
    if choice == 0:
        length = _rand_len(rng, 1, min(8, remaining))
        return ''.join(rng.choice('0123456789') for _ in range(length))
    elif choice == 1:
        length = _rand_len(rng, 1, min(10, remaining))
        return _asc_seq(length)
    elif choice == 2:
        length = _rand_len(rng, 1, min(10, remaining))
        return _desc_seq(length)
    elif choice == 3:
        length = _rand_len(rng, 1, min(12, remaining))
        return _repeat_digit(rng.choice('0123456789'), length)
    elif choice == 4:
        s = rng.choice(_patterns)
        return s[:remaining] if len(s) > remaining else s
    else:
        # phone-like: country code + local
        country = rng.choice(["1", "44", "49", "33", "81", "61", "55", "86", "7", "34"])
        if len(country) >= remaining:
            return country[:remaining]
        local_len = max(1, min(remaining - len(country), _rand_len(rng, 1, 12)))
        local = ''.join(rng.choice('0123456789') for _ in range(local_len))
        s = country + local
        return s[:remaining]

def _assemble_number(rng: random.Random) -> str:
    size_choices = [1, 2, 3, 4, 5, 7, 8, 9, 10, 11, 12, 13, 15, 16, 20, 32]
    weights = [1, 1, 2, 2, 3, 4, 4, 5, 6, 6, 5, 4, 3, 3, 2, 1]
    total_len = rng.choices(size_choices, weights=weights, k=1)[0]

    out = []
    remaining = total_len

    # Only digit prefixes are allowed
    prefixes = ["", "1", "0"]
    pref = rng.choice(prefixes)
    if pref and remaining > 0:
        pref = pref[:remaining]
        out.append(pref)
        remaining -= len(pref)

    while remaining > 0:
        chunk = _random_chunk(rng, remaining)
        if not chunk:
            chunk = rng.choice('0123456789')
        if len(chunk) > remaining:
            chunk = chunk[:remaining]
        out.append(chunk)
        remaining -= len(chunk)

    s = ''.join(out)
    if not s:
        s = "0"
    return s[:MAX_LEN]

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Occasionally pick one of the canonical patterns exactly
    if rng.random() < 0.25:
        core = rng.choice(_patterns)
        # Optionally extend with a random suffix up to MAX_LEN
        if rng.random() < 0.5:
            remaining = MAX_LEN - len(core)
            if remaining > 0:
                suffix_len = _rand_len(rng, 0, min(8, remaining))
                suffix = ''.join(rng.choice('0123456789') for _ in range(suffix_len))
                core = (core + suffix)[:MAX_LEN]
        digits = core
    else:
        digits = _assemble_number(rng)

    digits = ''.join(ch for ch in digits if ch.isdigit())[:MAX_LEN]
    if not digits:
        digits = '0'

    return digits.encode('ascii')

