        if t == 0:
            s = s.lower()
        elif t == 1:
            s = s.upper()
        elif t == 2:
            # Insert an extra underscore or character at random pos
            pos = rng.randrange(len(s) + 1)
            ch = rng.choice(["_", rng.choice(_IDENT_CHARS)])
            s = s[:pos] + ch + s[pos:]
        elif t == 3 and len(s) > 0:
            # Delete a random character
            pos = rng.randrange(len(s))
            s = s[:pos] + s[pos + 1:]
        elif t == 4:
            # Replace a segment separated by '_'
            parts = s.split('_')
            if parts:
                idx = rng.randrange(len(parts))
                parts[idx] = _rand_ident(rng, 1, rng.randint(1, 8))
                s = "_".join(parts)
        elif t == 5:
            # Append a short random suffix
            s = s + rng.choice(["_X", "_ALT", "__", "0", str(rng.randint(2, 99))])
        else:
            # Shuffle some characters locally
            if len(s) > 3:
                i = rng.randrange(len(s) - 1)
                s = s[:i] + s[i+1] + s[i] + s[i+2:]
    return s


def _random_invalid(rng: random.Random) -> str:
    p = rng.random()
    if p < 0.35:
        # Curated base plus slight randomization
        s = rng.choice(_INVALID_INTERESTING_BASE)
        if rng.random() < 0.6 and s:
            # Insert/append tiny noise
            if rng.random() < 0.5:
                s = s + rng.choice(["_", "-", str(rng.randint(0, 9))])
            else:
                pos = rng.randrange(len(s))
                s = s[:pos] + rng.choice(_IDENT_CHARS) + s[pos:]
        return s
    elif p < 0.7:
        return _rand_ident(rng, 1, rng.randint(4, 64))
    else:
        return _mutate_valid_like(rng)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Bias toward valid but ensure ample invalid diversity.
    make_valid = rng.random() < 0.5

    if make_valid:
        # Occasionally vary case to still be valid? The parser is case-sensitive, so keep exact.
        s = rng.choice(_VALID_ENUM_NAMES)
    else:
        s = _random_invalid(rng)

    # Ensure the size cap (fuzzer truncates >64, but we keep <= 128 then trim to 64)
    if len(s) > 64:
        s = s[:64]

    return s.encode('utf-8')
